<?php
 namespace Pterodactyl\Services\Dezerx\Ai; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use GuzzleHttp\Exception\TransferException; use Pterodactyl\Repositories\Wings\DaemonRepository; class ServerLogs extends DaemonRepository { public const MAX_LINES = 100; public function tail(Server $server, int $lines = self::MAX_LINES): ?array { $lines = max(1, min(self::MAX_LINES, $lines)); try { $response = $this->setServer($server)->getHttpClient()->get( sprintf('/api/servers/%s/logs?size=%d', $server->uuid, $lines) ); } catch (TransferException $exception) { Log::warning('The assistant could not read a server console', [ 'server' => $server->uuid, 'reason' => $exception->getMessage(), ]); return null; } catch (Throwable) { return null; } $body = json_decode($response->getBody()->__toString(), true); $data = is_array($body) ? ($body['data'] ?? $body) : null; if (!is_array($data)) { return null; } return array_values(array_map( static fn ($line) => self::plain((string) $line), array_slice($data, -$lines), )); } private static function plain(string $line): string { return (string) preg_replace('/\e\[[0-9;]*[A-Za-z]/', '', $line); } } 